+@test "VALID_MODEL_PATTERNS admit the fable short alias and the gpt -pro suffix" {
+    pattern_accepts fable
+    pattern_accepts gpt-5.5-pro
+    pattern_accepts gpt-5.3-codex
+    pattern_accepts opus
