+
+@test "VALID_MODEL_PATTERNS still reject shapes outside the grammar" {
+    local m
+    for m in claude-opus claude-fable- claude-fable-5- claude-opus-5-5-5 claude-poet-5 fables gpt-5.5-mini gpt-5 skeptic 'claude-opus-5;id'; do
